import{_ as r,K as o,a as n,c as l,ac as t,b as a,q as i}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"五子棋：自由规则与禁手规则的区别","description":"先约定胜负口径，再通过长连与双三例子区分自由五子棋、恰好五连和连珠。","frontmatter":{"title":"五子棋：自由规则与禁手规则的区别","description":"先约定胜负口径，再通过长连与双三例子区分自由五子棋、恰好五连和连珠。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"五子棋入门","summary":"先约定胜负口径，再通过长连与双三例子区分自由五子棋、恰好五连和连珠。","status":"active","related":[{"title":"五子棋：活三、冲四与连续威胁","link":"/life/personal/chess/gomoku/threats","kind":"棋类入门","scope":"general","audience":"general"},{"title":"五子棋：先手、攻防与关键落点","link":"/life/personal/chess/gomoku/attack-defense","kind":"棋类入门","scope":"general","audience":"general"},{"title":"五子棋：识别漏防与重复错误","link":"/life/personal/chess/gomoku/review","kind":"棋类入门","scope":"general","audience":"general"}],"prev":false,"next":{"text":"五子棋：活三、冲四与连续威胁","link":"/life/personal/chess/gomoku/threats"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"五子棋：活三、冲四与连续威胁","link":"/life/personal/chess/gomoku/threats"}},"headers":[],"relativePath":"life/personal/chess/gomoku/rules.md","filePath":"life/personal/chess/gomoku/rules.md"}'),d={name:"life/personal/chess/gomoku/rules.md"},p={class:"chess-example"},c={class:"chess-figure"};function h(u,e,_,g,m,k){const s=o("ArticleImage");return n(),l("div",null,[e[1]||(e[1]=t('<h1 id="五子棋-自由规则与禁手规则的区别" tabindex="-1">五子棋：自由规则与禁手规则的区别 <a class="header-anchor" href="#五子棋-自由规则与禁手规则的区别" aria-label="Permalink to &quot;五子棋：自由规则与禁手规则的区别&quot;">​</a></h1><p>五子棋最容易发生的争执不是谁先连五，而是开局没有约定规则：六颗算不算赢？黑方能不能双三？是否交换先后手？先把这些说清楚，后面的战术才有共同前提。</p><h2 id="共同的基本动作" tabindex="-1">共同的基本动作 <a class="header-anchor" href="#共同的基本动作" aria-label="Permalink to &quot;共同的基本动作&quot;">​</a></h2><p>常见棋盘是 15×15 交叉点。双方轮流在空点放一子，落下后不移动，也不像围棋那样提子。横、竖和两条斜线都可以连成胜形，但必须连续，不能隔着空点或对方棋子。</p><p>本文教学坐标 A～O 从左到右、1～15 从下到上，不跳过字母 I。X 为黑、O 为白，<code>.</code> 是空点。除专门讨论禁手的地方，其余练习使用双方事先约定的自由规则：五颗及以上连续成线获胜，无黑方禁手，黑先。</p><h2 id="三种常见口径别混用" tabindex="-1">三种常见口径别混用 <a class="header-anchor" href="#三种常见口径别混用" aria-label="Permalink to &quot;三种常见口径别混用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>口径</th><th>连成六颗</th><th>黑方双三、双四</th><th>开局</th></tr></thead><tbody><tr><td>本课程自由练习规则</td><td>算胜</td><td>不设禁手</td><td>黑先，轮流落子</td></tr><tr><td>恰好五连规则</td><td>长连不算胜，继续下</td><td>不因此禁止</td><td>可以采用交换规则</td></tr><tr><td>连珠 Renju</td><td>黑方长连有禁手问题；白长连可胜</td><td>黑方受限制</td><td>正式比赛还规定开局程序</td></tr></tbody></table><p>RIF 的国际 Gomoku 规则采用恰好五连和 Swap2 开局，不能把它当成所有自由五子棋的统一规则。Swap2 的作用是通过选择颜色减少先手优势；第一次练基本走法时可以先不用，但参加相应比赛就不能省略。</p><h2 id="用一条线看懂长连" tabindex="-1">用一条线看懂长连 <a class="header-anchor" href="#用一条线看懂长连" aria-label="Permalink to &quot;用一条线看懂长连&quot;">​</a></h2>',9)),a("div",p,[a("div",c,[a("p",null,[i(s,{src:"/images/chess/gomoku-overline.svg",alt:"长连对照 · 局部棋形。黑走 G8 后连成六颗；胜负取决于约定规则。"})])]),e[0]||(e[0]=t(`<div class="chess-explanation"><p>第 8 行局部，D8、E8、F8、H8、I8 都是黑子，G8 为空：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>列  C D E F G H I J</span></span>
<span class="line"><span>8   . X X X . X X .</span></span></code></pre></div><p>黑下 G8 后，D8～I8 成为连续六颗。按本课程自由练习规则，黑胜；按恰好五连规则，这条线不构成胜利；按连珠规则，黑方有长连禁手问题。<strong>相同棋盘，规则不同，结论不同。</strong></p></div>`,1))]),e[2]||(e[2]=t('<h2 id="禁手不是-看见两个三-就判" tabindex="-1">禁手不是“看见两个三”就判 <a class="header-anchor" href="#禁手不是-看见两个三-就判" aria-label="Permalink to &quot;禁手不是“看见两个三”就判&quot;">​</a></h2><p>连珠对黑方的双三、双四和长连有限制，但判断“双三”需要看形成的三能否按合法步骤发展为活四，有些外观相似的棋形不是真正的双三。还要处理同时成五等规则条件。</p><p>例如黑在 G8、I8、H7、H9，周围开阔，黑再下 H8，会在横竖两方向形成连续三，各自有正常发展空间，这是典型需要检查双三的形状。若周围被堵，或发展点本身会形成禁手，不能照搬结论。初学时先用自由规则学清威胁，再单独学连珠裁定。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li><code>XX.XXX</code> 算连续五吗？<strong>不算。</strong> 中间有空点。</li><li>自由规则里两端被白子堵住，但中间已经连续五颗黑子，黑赢吗？<strong>赢。</strong> 本课程没有“两头堵就不算”的额外约定。</li><li>在线平台显示黑方禁手，能说软件错了吗？<strong>先检查房间规则。</strong> 可能选的是连珠，而不是自由规则。</li></ol><p>开始每盘前问三句：“五还是五以上？有没有禁手？怎样开局？”这比开局后争论某个棋形更省事。</p><p>规则对照：<a href="https://gomoku.renju.net/gomokurules/" target="_blank" rel="noopener noreferrer">RIF 国际 Gomoku 规则</a>、<a href="https://www.renju.net/rifrules/" target="_blank" rel="noopener noreferrer">RIF 连珠规则</a>。本文自由练习规则已在上方明确约定，棋形为原创示例。</p>',7))])}const x=r(d,[["render",h]]);export{b as __pageData,x as default};
